<?php

namespace App\Actions;

use App\Models\Consultation;
use App\Models\Discharge;
use App\Models\Doctor;
use App\Models\Patient;
use App\Models\Prescription;
use App\Models\Turn;
use Illuminate\Support\Collection;

class BuildClinicalHistory
{
    /**
     * Build a unified clinical history for a patient.
     *
     * Returns a list of entries (consulta | receta | alta) ordered most-recent first.
     * Each entry carries a `mine` flag: true if it was generated by `$callerDoctor`.
     *
     * Rules:
     * - Each consultation note → `consulta` entry.
     * - Each prescription on a turn that has NO consultation note → standalone `receta` entry.
     * - Each discharge on a turn that has NO consultation note → standalone `alta` entry.
     *
     * @return list<array<string, mixed>>
     */
    public function handle(Patient $patient, Doctor $callerDoctor): array
    {
        // Eager-load all turns with their related data (no N+1)
        $turns = Turn::with([
            'doctor.specialty',
            'consultation',
            'prescription.items',
            'discharge',
        ])
            ->where('patient_id', $patient->id)
            ->whereIn('status', ['atendido', 'en_consulta', 'espera'])
            ->get();

        $entries = collect();

        foreach ($turns as $turn) {
            $mine = $turn->doctor_id === $callerDoctor->id;

            // 1. Consultation note present → consulta entry
            if ($turn->consultation !== null) {
                $entries->push($this->makeConsultaEntry($turn, $turn->consultation, $mine));
                continue; // prescription (if any) is included inside the consulta entry
            }

            // 2. No consultation note: standalone prescription → receta entry
            if ($turn->prescription !== null) {
                $entries->push($this->makeRecetaEntry($turn, $turn->prescription, $mine));
            }

            // 3. No consultation note: standalone discharge → alta entry
            if ($turn->discharge !== null) {
                $entries->push($this->makeAltaEntry($turn, $turn->discharge, $mine));
            }
        }

        // Sort by date descending
        return $entries
            ->sortByDesc('date')
            ->values()
            ->all();
    }

    /** @return array<string, mixed> */
    private function makeConsultaEntry(Turn $turn, Consultation $c, bool $mine): array
    {
        return [
            'type' => 'consulta',
            'date' => $c->consulted_at->toIso8601String(),
            'mine' => $mine,
            'doctor' => [
                'id' => $turn->doctor->id,
                'full_name' => $turn->doctor->name,
                'specialty' => $turn->doctor->specialty->name,
            ],
            'motivo_consulta' => $c->motivo_consulta,
            'historia_enfermedad' => $c->historia_enfermedad,
            'examen_fisico' => $c->examen_fisico,
            'diagnosticos' => $c->diagnosticos,
            'plan_tratamiento' => $c->plan_tratamiento,
            'vitals' => [
                'peso' => $c->peso,
                'talla' => $c->talla,
                'temp' => $c->temp,
                'presion_arterial' => $c->presion_arterial,
                'frecuencia_cardiaca' => $c->frecuencia_cardiaca,
                'frecuencia_respiratoria' => $c->frecuencia_respiratoria,
                'saturacion_o2' => $c->saturacion_o2,
                'glucemia' => $c->glucemia,
            ],
            'discharge' => $turn->discharge ? [
                'type' => $turn->discharge->type,
                'destination' => $turn->discharge->destination,
                'discharge_diagnosis' => $turn->discharge->discharge_diagnosis,
                'discharged_at' => $turn->discharge->discharged_at->toIso8601String(),
            ] : null,
            'prescription' => $turn->prescription
                ? $this->formatPrescription($turn->prescription)
                : null,
        ];
    }

    /** @return array<string, mixed> */
    private function makeRecetaEntry(Turn $turn, Prescription $p, bool $mine): array
    {
        return [
            'type' => 'receta',
            'date' => $p->prescribed_at->toIso8601String(),
            'mine' => $mine,
            'doctor' => [
                'id' => $turn->doctor->id,
                'full_name' => $turn->doctor->name,
                'specialty' => $turn->doctor->specialty->name,
            ],
            'prescription' => $this->formatPrescription($p),
        ];
    }

    /** @return array<string, mixed> */
    private function makeAltaEntry(Turn $turn, Discharge $d, bool $mine): array
    {
        return [
            'type' => 'alta',
            'date' => $d->discharged_at->toIso8601String(),
            'mine' => $mine,
            'doctor' => [
                'id' => $turn->doctor->id,
                'full_name' => $turn->doctor->name,
                'specialty' => $turn->doctor->specialty->name,
            ],
            'discharge' => [
                'type' => $d->type,
                'destination' => $d->destination,
                'discharge_diagnosis' => $d->discharge_diagnosis,
                'discharged_at' => $d->discharged_at->toIso8601String(),
            ],
        ];
    }

    /** @return array<string, mixed> */
    private function formatPrescription(Prescription $p): array
    {
        return [
            'id' => $p->id,
            'general_instructions' => $p->general_instructions,
            'prescribed_at' => $p->prescribed_at->toIso8601String(),
            'items' => $p->items->map(fn ($item) => [
                'id' => $item->id,
                'position' => $item->position,
                'medication' => $item->medication,
                'route' => $item->route,
                'dose' => $item->dose,
                'frequency' => $item->frequency,
                'duration_days' => $item->duration_days,
                'is_continuous' => $item->is_continuous,
                'quantity' => $item->quantity,
            ])->all(),
        ];
    }
}
